#include "../src/openpangu_weights.h"
#include <iostream>
int main(int argc,char**argv){if(argc!=3){std::cerr<<"usage: openpangu_load_probe MANIFEST CHECKPOINT\n";return 2;}try{if(std::string(argv[1])=="--validate"){openpangu::LoadPlan plan(argv[2]);std::cout<<"valid load plan\n";return 0;}openpangu::LoadPlan plan(argv[1]);openpangu::checked(aclInit(nullptr),"init");openpangu::checked(aclrtSetDevice(plan.device),"device");{openpangu::ResidentWeights weights(plan,argv[2],true);std::cout<<"{\"status\":\"passed\",\"rank\":"<<plan.rank<<",\"weights\":"<<weights.tensors.size()<<",\"stored_bytes\":"<<weights.stored_bytes<<",\"prepared_bytes\":"<<weights.prepared_bytes<<",\"full_upload_readback\":true}\n";}openpangu::checked(aclrtResetDevice(plan.device),"reset");openpangu::checked(aclFinalize(),"finalize");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
